package com.dy.artisan3d.navigationimport kotlinx.serialization.Serializable@Serializablesealed class Screen {    @Serializable    data object ChooseLanguage : Screen() // : Screen() qo'shildi    @Serializable    data object OnBoarding : Screen() // : Screen() qo'shildi    @Serializable    data object Main : Screen() // : Screen() qo'shildi    @Serializable    data class Products(val categoryId: Int, val brandId: Int, val title: String) : Screen()    @Serializable    data class ProductDetail(val productId: Int) : Screen()    @Serializable    data class ArticleDetail(val articleId: Int) : Screen()    @Serializable    data object Settings : Screen()}